"use client";
import { cn } from "@/lib/utils";
import {
  panel as surfacePanel,
  secondary as surfaceSecondary,
} from "@/lib/takt-surface";

import { useState } from "react";

export function GhostSuggestion({
  className,
  options = ["Build a catalog", "Create a layout", "Open a file"],
  onChange,
}: {
  className?: string;
  options?: string[];
  onChange?: (value: string) => void;
}) {
  const [value, setValue] = useState("");
  const [dismissed, setDismissed] = useState(false);
  const [atEnd, setAtEnd] = useState(true);
  const match =
    !dismissed &&
    atEnd &&
    value.length > 0 &&
    options.find(
      (x) =>
        x.toLowerCase().startsWith(value.toLowerCase()) &&
        x.toLowerCase() !== value.toLowerCase(),
    );
  function update(v: string) {
    setValue(v);
    setDismissed(false);
    onChange?.(v);
  }
  return (
    <div
      className={cn(surfacePanel + " grid w-64 max-w-full gap-2", className)}
    >
      <label className="relative flex min-h-11 items-center rounded-lg border border-foreground/15 bg-background px-3 text-sm focus-within:border-foreground/50">
        <span
          aria-hidden
          className="pointer-events-none absolute inset-x-3 overflow-hidden whitespace-pre text-muted-foreground"
        >
          <span className="invisible">{value}</span>
          {match ? match.slice(value.length) : ""}
        </span>
        <input
          aria-label="Autocomplete"
          spellCheck={false}
          autoComplete="off"
          placeholder="Start typing…"
          onSelect={(e) => {
            const n = e.currentTarget;
            setAtEnd(
              n.selectionStart === n.value.length &&
                n.selectionEnd === n.value.length &&
                n.scrollLeft === 0,
            );
          }}
          className="relative w-full min-w-0 bg-transparent caret-foreground outline-none! selection:bg-primary/20"
          value={value}
          onChange={(e) => update(e.target.value)}
          onKeyDown={(e) => {
            if (e.nativeEvent.isComposing || e.keyCode === 229) return;

            if (e.key === "Escape") {
              setDismissed(true);
              return;
            }
            if (
              (e.key === "ArrowRight" ||
                (e.key === "Tab" && !e.shiftKey && value.length > 0)) &&
              match &&
              e.currentTarget.selectionStart === value.length
            ) {
              e.preventDefault();
              update(match);
            }
          }}
        />
      </label>
      <button
        type="button"
        className={surfaceSecondary}
        disabled={!match}
        onClick={() => match && update(match)}
      >
        Accept{" "}
        <kbd className="ml-1 rounded border bg-muted px-1 font-mono text-[9px]">
          Tab
        </kbd>
      </button>
    </div>
  );
}

// Semantic shadcn colors keep the surfaces usable in a host project's own theme.
export const panel =
  "rounded-2xl border border-foreground/10 bg-card p-4 text-sm text-card-foreground shadow-[0_2px_5px_#0000000a,0_8px_18px_-12px_#0003]";
export const field =
  "min-h-10 min-w-0 w-full rounded-xl border border-foreground/10 bg-muted/70 px-3 text-sm text-foreground outline-none motion-safe:transition-[background-color,box-shadow] focus:bg-background focus:ring-1 focus:ring-foreground/35";
export const action =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-xl border border-foreground/10 bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground shadow-sm outline-offset-4 motion-safe:transition-[transform,box-shadow] motion-safe:active:translate-y-px motion-safe:active:scale-[.97] disabled:cursor-default disabled:opacity-50";
export const secondary =
  "inline-flex min-h-9 cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-foreground/10 bg-background px-3 text-xs font-medium text-foreground outline-offset-2 hover:bg-muted motion-safe:transition-[transform,background-color] motion-safe:active:scale-[.96] disabled:cursor-default disabled:opacity-45";
